import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.*;
import com.sun.net.httpserver.*;

public class ReportService {
    private static final String DB_URL = System.getenv("DB_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/reports", ReportService::handleReports);
        server.createContext("/api/export", ReportService::handleExport);
        server.setExecutor(null);
        server.start();
    }

    static void handleReports(HttpExchange exchange) throws IOException {
        if (!"GET".equals(exchange.getRequestMethod())) {
            exchange.sendResponseHeaders(405, 0); exchange.close(); return;
        }
        String query = exchange.getRequestURI().getQuery();
        Map<String, String> params = parseQuery(query);
        String department = params.getOrDefault("dept", "engineering");
        String quarter = params.getOrDefault("quarter", "Q1");
        // Validate quarter format
        if (!quarter.matches("Q[1-4]")) {
            sendResponse(exchange, 400, "Invalid quarter format");
            return;
        }
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Department is user-controlled and concatenated directly
            String sql = "SELECT report_id, title, created_at, author FROM reports WHERE department = '" + department + "' AND quarter = '" + quarter + "' ORDER BY created_at DESC";
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(sql);
            StringBuilder json = new StringBuilder("[");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",");
                json.append(String.format("{\"id\":%d,\"title\":\"%s\",\"date\":\"%s\",\"author\":\"%s\"}",
                    rs.getInt(1), rs.getString(2), rs.getString(3), rs.getString(4)));
                first = false;
            }
            json.append("]");
            sendResponse(exchange, 200, json.toString());
        } catch (SQLException e) {
            sendResponse(exchange, 500, "{\"error\":\"Database error\"}");
        }
    }

    static void handleExport(HttpExchange exchange) throws IOException {
        if (!"POST".equals(exchange.getRequestMethod())) {
            exchange.sendResponseHeaders(405, 0); exchange.close(); return;
        }
        String body = new String(exchange.getRequestBody().readAllBytes());
        // Parse simple JSON manually (no library dependency)
        String filename = extractJsonField(body, "filename");
        String content = extractJsonField(body, "content");
        if (filename == null || content == null) {
            sendResponse(exchange, 400, "Missing fields"); return;
        }
        // Sanitize filename - remove path separators
        filename = filename.replaceAll("[/\\\\]", "").replaceAll("\\.\\.", "");
        File exportDir = new File("/tmp/exports");
        exportDir.mkdirs();
        File outFile = new File(exportDir, filename);
        try (FileWriter fw = new FileWriter(outFile)) {
            fw.write(content);
        }
        sendResponse(exchange, 200, "{\"path\":\"" + outFile.getAbsolutePath() + "\"}");
    }

    static String extractJsonField(String json, String field) {
        int idx = json.indexOf("\"" + field + "\"");
        if (idx == -1) return null;
        int colon = json.indexOf(":", idx);
        int start = json.indexOf("\"", colon) + 1;
        int end = json.indexOf("\"", start);
        return (start > 0 && end > start) ? json.substring(start, end) : null;
    }

    static Map<String, String> parseQuery(String query) {
        Map<String, String> map = new HashMap<>();
        if (query == null) return map;
        for (String param : query.split("&")) {
            String[] kv = param.split("=", 2);
            if (kv.length == 2) map.put(URLDecoder.decode(kv[0], java.nio.charset.StandardCharsets.UTF_8),
                                         URLDecoder.decode(kv[1], java.nio.charset.StandardCharsets.UTF_8));
        }
        return map;
    }

    static void sendResponse(HttpExchange exchange, int code, String body) throws IOException {
        exchange.getResponseHeaders().set("Content-Type", "application/json");
        byte[] bytes = body.getBytes();
        exchange.sendResponseHeaders(code, bytes.length);
        exchange.getResponseBody().write(bytes);
        exchange.close();
    }
}
